import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CmvPqeTF.js";const b=JSON.parse('{"title":"连接与分组管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/connections.md","filePath":"guide/connections.md","lastUpdated":1788361893000}'),n={name:"guide/connections.md"};function s(o,t,l,i,h,c){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="连接与分组管理" tabindex="-1">连接与分组管理 <a class="header-anchor" href="#连接与分组管理" aria-label="Permalink to &quot;连接与分组管理&quot;">​</a></h1><p>侧栏「连接」面板（ActivityBar 第一个图标）是 vShell 的主入口：分组树 + 连接列表，新建、编辑、双击连接打开终端。</p><hr><h2 id="_1-界面结构" tabindex="-1">1. 界面结构 <a class="header-anchor" href="#_1-界面结构" aria-label="Permalink to &quot;1. 界面结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────┐</span></span>
<span class="line"><span>│ 连接      [📁+] [➕]     │  标题栏：新建分组 / 新建连接</span></span>
<span class="line"><span>├─────────────────────────┤</span></span>
<span class="line"><span>│ ▾ 生产环境               │  分组（hover：➕ 新建连接 ✏️ 重命名 🗑 删除）</span></span>
<span class="line"><span>│    ├─ web-01            │  连接（hover：⚡ 连接 ✏️ 编辑 🗑 删除）</span></span>
<span class="line"><span>│    └─ db-01             │</span></span>
<span class="line"><span>│ ▾ 测试环境               │</span></span>
<span class="line"><span>│    └─ test-01           │</span></span>
<span class="line"><span>│ （未分组连接）            │  未分组的连接排在根级末尾</span></span>
<span class="line"><span>└─────────────────────────┘</span></span></code></pre></div><ul><li>分组按 <code>parent_id</code> 递归构树，默认展开全部</li><li>连接行显示 <code>名称</code> + <code>主机:端口</code></li><li>侧栏宽度可在 200–500px 间拖拽调整</li></ul><h2 id="_2-连接的建立与打开" tabindex="-1">2. 连接的建立与打开 <a class="header-anchor" href="#_2-连接的建立与打开" aria-label="Permalink to &quot;2. 连接的建立与打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>行为</th></tr></thead><tbody><tr><td><strong>双击连接</strong></td><td>建立 SSH 连接并打开终端标签</td></tr><tr><td>单击连接</td><td>切换到该连接已存在的第一个终端标签（不新建）</td></tr><tr><td>hover ⚡ 闪电</td><td>与双击等价，快速连接</td></tr><tr><td>拖拽连接到分组</td><td>修改所属分组（<code>MoveConnection</code>）</td></tr></tbody></table><p>连接失败时弹出错误对话框，包含后端原始错误与提示「无法连接到 {host}，请检查主机地址、端口和认证信息」。</p><h2 id="_3-连接表单" tabindex="-1">3. 连接表单 <a class="header-anchor" href="#_3-连接表单" aria-label="Permalink to &quot;3. 连接表单&quot;">​</a></h2><p>点击 ➕ 新建或 ✏️ 编辑打开连接表单（模态，宽 480px）：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>必填</td></tr><tr><td>分组</td><td>下拉选择，<code>-</code> 表示未分组</td></tr><tr><td>主机</td><td>必填</td></tr><tr><td>端口</td><td>1–65535，默认 22</td></tr><tr><td>用户名</td><td>必填</td></tr><tr><td>认证方式</td><td>密码 / 私钥 / SSH Agent / 交互式</td></tr><tr><td>密码 / 私钥 / 口令</td><td>依据认证方式显示，保存时 AES-256-GCM 加密入库</td></tr></tbody></table><h3 id="_3-1-认证方式" tabindex="-1">3.1 认证方式 <a class="header-anchor" href="#_3-1-认证方式" aria-label="Permalink to &quot;3.1 认证方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>认证方式</th><th>实现状态</th></tr></thead><tbody><tr><td><strong>密码</strong></td><td>直接输入密码。编辑时可点钥匙图标回显已存密码（再点一次清空，留空表示保持不变）</td></tr><tr><td><strong>私钥</strong></td><td>见下文「密钥来源」</td></tr><tr><td><strong>SSH Agent</strong></td><td>表单中可选，但<strong>后端尚未实现</strong>，连接时会报错 <code>ssh agent auth not yet implemented</code></td></tr><tr><td><strong>交互式</strong></td><td>Keyboard-Interactive：输入密码，服务器的每个提问都会以该密码应答</td></tr></tbody></table><h3 id="_3-2-私钥认证的两种来源" tabindex="-1">3.2 私钥认证的两种来源 <a class="header-anchor" href="#_3-2-私钥认证的两种来源" aria-label="Permalink to &quot;3.2 私钥认证的两种来源&quot;">​</a></h3><ul><li><strong>从密钥管理选择</strong>：下拉列出<a href="./keys.html">密钥管理</a>中的密钥（<code>名称 (类型 - 注释)</code>，可搜索），选中后自动读取私钥内容；若该密钥有口令，会提示「该密钥有密码保护，请输入密钥口令」</li><li><strong>手动粘贴</strong>：textarea 粘贴私钥内容。编辑时可用钥匙图标回显已存私钥，回显后自动与 <code>~/.ssh</code> 中管理的密钥逐个比对，提示「与密钥管理中的「xx」内容一致」或「与密钥管理中的任何密钥都不匹配」</li></ul><p>编辑已有连接时，若其私钥仍存在于密钥管理，会自动还原为「从密钥管理选择」模式。</p><h3 id="_3-3-校验" tabindex="-1">3.3 校验 <a class="header-anchor" href="#_3-3-校验" aria-label="Permalink to &quot;3.3 校验&quot;">​</a></h3><p>保存前校验（<code>message.warning</code> 提示）：名称非空、主机非空、新建时私钥认证必须提供私钥内容。</p><h2 id="_4-分组操作" tabindex="-1">4. 分组操作 <a class="header-anchor" href="#_4-分组操作" aria-label="Permalink to &quot;4. 分组操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>新建分组</td><td>标题栏 📁+ 按钮创建根分组</td></tr><tr><td>重命名</td><td>hover 分组行点 ✏️</td></tr><tr><td>删除</td><td>hover 点 🗑；<strong>组内有连接时会被拒绝</strong>，提示先将连接移出</td></tr><tr><td>移动连接</td><td>拖拽连接到目标分组；也可以拖到某连接的前后调整排序</td></tr></tbody></table><blockquote><p>数据模型支持分组嵌套（<code>parent_id</code>），当前界面仅提供根分组的创建入口；分组本身不可拖拽。</p></blockquote><h2 id="_5-删除连接与联动清理" tabindex="-1">5. 删除连接与联动清理 <a class="header-anchor" href="#_5-删除连接与联动清理" aria-label="Permalink to &quot;5. 删除连接与联动清理&quot;">​</a></h2><ul><li>删除连接需确认；后端会先断开该连接的 SSH 会话，再删除记录</li><li>关闭某连接的最后一个终端标签时，会同时关闭其 SFTP 面板；<code>⌘W</code>（File → Close）则<strong>断开整条连接</strong>（含监控）并关闭标签，详见<a href="./terminal.html">终端使用</a></li></ul><h2 id="_6-数据与安全" tabindex="-1">6. 数据与安全 <a class="header-anchor" href="#_6-数据与安全" aria-label="Permalink to &quot;6. 数据与安全&quot;">​</a></h2><ul><li>连接存储在本地 SQLite（见<a href="./../dev/storage-crypto.html">数据存储与加密</a>）</li><li><code>password</code> / <code>private_key</code> / <code>key_passphrase</code> 三列只存 AES-256-GCM 密文；连接列表查询<strong>不返回</strong>这三个字段，需要时通过 <code>GetPassword</code> / <code>GetPrivateKey</code> / <code>GetKeyPassphrase</code> 单独解密读取（用于表单回显）</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./keys.html">SSH 密钥管理</a> —— 私钥来源「从密钥管理选择」背后的管理体系</li><li><a href="./ssh-config.html">~/.ssh/config 导入导出</a> —— 批量把现有主机配置变成连接</li></ul>`,29)])])}const u=a(n,[["render",s]]);export{b as __pageData,u as default};
